// Writes src/migrations.ts from migrations/*.sql (the SQL files are the source of truth; the Worker has no
// filesystem, so it carries them as strings). `pnpm gen` after editing a migration; a test fails when they differ.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dirname, "..", "migrations");
const list = readdirSync(dir)
  .filter((f) => f.endsWith(".sql"))
  .sort()
  .map((f) => ({ name: f.replace(/\.sql$/, ""), sql: readFileSync(join(dir, f), "utf8") }));

const out =
  "// Generated by scripts/gen-migrations.mjs from migrations/*.sql: do not edit.\n" +
  'import type { Migration } from "@l0wservices/core";\n\n' +
  `export const BOARD_MIGRATIONS: Migration[] = ${JSON.stringify(list, null, 2)};\n`;
writeFileSync(join(import.meta.dirname, "..", "src", "migrations.ts"), out);
console.log(`wrote ${list.length} migration(s)`);
